-- Run in Supabase SQL Editor before enabling cloud accounts.
create extension if not exists pgcrypto;
create table if not exists public.player_profiles(id uuid primary key references auth.users(id) on delete cascade,display_name text not null default 'Player' check(char_length(display_name) between 1 and 24),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists public.player_saves(id uuid primary key default gen_random_uuid(),user_id uuid not null references auth.users(id) on delete cascade,game_id text not null check(game_id in('neon-dodge','snake','2048','minesweeper')),save_data jsonb not null default '{}'::jsonb check(pg_column_size(save_data)<65536),updated_at timestamptz not null default now(),unique(user_id,game_id));
create table if not exists public.player_achievements(user_id uuid not null references auth.users(id) on delete cascade,achievement_id text not null check(char_length(achievement_id) between 1 and 64),unlocked_at timestamptz not null default now(),primary key(user_id,achievement_id));
alter table public.player_profiles enable row level security;alter table public.player_saves enable row level security;alter table public.player_achievements enable row level security;
drop policy if exists "Profiles own read" on public.player_profiles;create policy "Profiles own read" on public.player_profiles for select to authenticated using((select auth.uid())=id);
drop policy if exists "Profiles own insert" on public.player_profiles;create policy "Profiles own insert" on public.player_profiles for insert to authenticated with check((select auth.uid())=id);
drop policy if exists "Profiles own update" on public.player_profiles;create policy "Profiles own update" on public.player_profiles for update to authenticated using((select auth.uid())=id) with check((select auth.uid())=id);
drop policy if exists "Saves own read" on public.player_saves;create policy "Saves own read" on public.player_saves for select to authenticated using((select auth.uid())=user_id);
drop policy if exists "Saves own insert" on public.player_saves;create policy "Saves own insert" on public.player_saves for insert to authenticated with check((select auth.uid())=user_id);
drop policy if exists "Saves own update" on public.player_saves;create policy "Saves own update" on public.player_saves for update to authenticated using((select auth.uid())=user_id) with check((select auth.uid())=user_id);
drop policy if exists "Saves own delete" on public.player_saves;create policy "Saves own delete" on public.player_saves for delete to authenticated using((select auth.uid())=user_id);
drop policy if exists "Achievements own read" on public.player_achievements;create policy "Achievements own read" on public.player_achievements for select to authenticated using((select auth.uid())=user_id);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path='' as $$begin insert into public.player_profiles(id,display_name) values(new.id,coalesce(nullif(left(new.raw_user_meta_data->>'display_name',24),''),'Player')) on conflict(id) do nothing;return new;end;$$;
drop trigger if exists on_auth_user_created on auth.users;create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
grant select,insert,update on public.player_profiles to authenticated;grant select,insert,update,delete on public.player_saves to authenticated;grant select on public.player_achievements to authenticated;